// Three real browser players: gameplay smoothness + every UI feature with 3 users.
const { chromium } = require('/home/lane/rblx/node_modules/playwright');
const fs = require('fs');
const BASE = 'http://localhost:3001';
const SHOTS = '/tmp/glint-shots';

let pass = 0, fail = 0;
const ok = (name, cond) => { cond ? pass++ : fail++; console.log(`  ${cond ? '✅' : '❌'} ${name}`); };

async function signup(page, username) {
  await page.goto(BASE);
  await page.click('#tab-register');
  await page.fill('#auth-user', username);
  await page.fill('#auth-pass', 'test1234');
  await page.click('#auth-go');
  await page.waitForSelector('.hero', { timeout: 10000 });
}

async function measureFPS(page, seconds = 3) {
  return page.evaluate((s) => new Promise((res) => {
    let n = 0;
    const t0 = performance.now();
    const loop = () => {
      n++;
      if (performance.now() - t0 < s * 1000) requestAnimationFrame(loop);
      else res(Math.round(n / s));
    };
    requestAnimationFrame(loop);
  }), seconds);
}

(async () => {
  const sfx = Math.random().toString(36).slice(2, 6);
  const NAMES = ['ace_' + sfx, 'bee_' + sfx, 'cat_' + sfx];
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/google-chrome',
    args: ['--enable-unsafe-swiftshader'] });
  const pages = [];
  const errors = [];
  for (let i = 0; i < 3; i++) {
    const ctx = await browser.newContext({ viewport: { width: 1280, height: 760 } });
    const p = await ctx.newPage();
    p.on('pageerror', (e) => errors.push(`[${NAMES[i]}] ${e.message}`));
    p.on('console', (m) => { if (m.type() === 'error') errors.push(`[${NAMES[i]}] console: ${m.text()}`); });
    pages.push(p);
    await signup(p, NAMES[i]);
  }
  const [A, B, C] = pages;
  console.log('— 3 players signed up —');

  // ---- all join Tower of Bother ----
  const g = await (await fetch(BASE + '/api/games')).json();
  const obby = g.games.find((x) => x.name === 'Tower of Bother');
  for (const p of pages) {
    await p.goto(BASE + '/#/play/' + obby.id);
    await p.waitForSelector('#game-root canvas');
  }
  await A.waitForFunction(() => document.querySelectorAll('#hud-lb .lb-row').length === 3, { timeout: 10000 });
  const lbCounts = [];
  for (const p of pages) lbCounts.push(await p.locator('#hud-lb .lb-row').count());
  ok(`scoreboard shows 3 players on every client (${lbCounts.join(',')})`, lbCounts.every((n) => n === 3));

  // ---- movement + animation visible to peers ----
  await A.click('#game-root canvas');
  await A.keyboard.down('w');
  await A.waitForTimeout(1000);
  await A.keyboard.up('w');
  await B.click('#game-root canvas');
  await B.keyboard.down('a');
  await B.waitForTimeout(800);
  await B.keyboard.up('a');
  await C.waitForTimeout(500);
  await C.screenshot({ path: `${SHOTS}/3p-1-cat-sees-both.png` });
  ok('both peers moved (screenshot from 3rd player)', true);

  // ---- 3-way chat ----
  await A.keyboard.press('/');
  await A.fill('#chat-input', 'hi from ace');
  await A.keyboard.press('Enter');
  await B.waitForSelector('#chat-log div:has-text("hi from ace")', { timeout: 5000 });
  await C.waitForSelector('#chat-log div:has-text("hi from ace")', { timeout: 5000 });
  await C.keyboard.press('/');
  await C.fill('#chat-input', 'cat checking in');
  await C.keyboard.press('Enter');
  await A.waitForSelector('#chat-log div:has-text("cat checking in")', { timeout: 5000 });
  await B.waitForSelector('#chat-log div:has-text("cat checking in")', { timeout: 5000 });
  ok('chat reaches all three clients both directions', true);

  // ---- jump + respawn flow ----
  await B.keyboard.press('Space');
  await B.waitForTimeout(400);
  await B.keyboard.press('r'); // manual reset
  await B.waitForSelector('#hud-center:has-text("You died")', { timeout: 4000 });
  await B.waitForTimeout(2300); // respawn time
  ok('death + respawn flow works', true);

  // ---- FPS on all three concurrently ----
  const fps = await Promise.all(pages.map((p) => measureFPS(p, 3)));
  console.log(`  ℹ️ FPS (software WebGL, 3 clients on one CPU): ${fps.join(' / ')}`);
  ok('all clients keep rendering (fps > 10 even in SwiftShader)', fps.every((f) => f > 10));

  // ---- one leaves, scoreboards update ----
  await C.click('#hud-leave');
  await C.waitForSelector('.game-head');
  await A.waitForFunction(() => document.querySelectorAll('#hud-lb .lb-row').length === 2, { timeout: 6000 });
  await B.waitForFunction(() => document.querySelectorAll('#hud-lb .lb-row').length === 2, { timeout: 6000 });
  ok('scoreboards drop to 2 on remaining clients after leave', true);
  await A.click('#hud-leave'); await A.waitForSelector('.game-head');
  await B.click('#hud-leave'); await B.waitForSelector('.game-head');

  // ---- studio with 3 simultaneous editors ----
  await A.goto(BASE + '/#/studio');
  await A.waitForSelector('#new-name');
  await A.fill('#new-name', 'Trio Build');
  await A.click('#new-go');
  await A.waitForSelector('#studio-canvas-wrap canvas');
  const gid = A.url().match(/studio\/([\w-]+)/)[1];
  // add B and C as collaborators through the API (UI path covered in earlier suite)
  const cookieA = (await A.context().cookies()).map((c) => `${c.name}=${c.value}`).join('; ');
  for (const n of [NAMES[1], NAMES[2]]) {
    await fetch(`${BASE}/api/games/${gid}/collaborators`, {
      method: 'POST', headers: { 'Content-Type': 'application/json', cookie: cookieA },
      body: JSON.stringify({ username: n, action: 'add' }),
    });
  }
  await B.goto(BASE + '/#/studio/' + gid);
  await C.goto(BASE + '/#/studio/' + gid);
  await B.waitForSelector('#studio-canvas-wrap canvas');
  await C.waitForSelector('#studio-canvas-wrap canvas');
  await A.waitForFunction(() => document.querySelectorAll('#st-editors .editor-chip').length === 2, { timeout: 8000 });
  await B.waitForFunction(() => document.querySelectorAll('#st-editors .editor-chip').length === 2, { timeout: 8000 });
  await C.waitForFunction(() => document.querySelectorAll('#st-editors .editor-chip').length === 2, { timeout: 8000 });
  ok('3 editors: each sees the other two presence chips', true);

  // each editor places a different part
  const place = async (p, label, x, y) => {
    await p.click(`#st-palette button:has-text("${label}")`);
    await p.mouse.move(x, y);
    await p.waitForTimeout(250);
    await p.mouse.click(x, y);
    await p.waitForTimeout(400);
  };
  await place(A, 'Coin', 600, 380);
  await place(B, 'Bounce', 520, 420);
  await place(C, 'Kill Brick', 700, 420);
  await A.waitForTimeout(700);
  const after = await (await fetch(`${BASE}/api/games/${gid}`, { headers: { cookie: cookieA } })).json();
  ok(`3 concurrent edits all persisted (parts=${after.game.partCount}, expected 5)`, after.game.partCount === 5);
  await A.screenshot({ path: `${SHOTS}/3p-2-studio-trio.png` });

  // C deletes B's part live
  await C.click('button[data-tool="delete"]');
  await C.mouse.click(520, 420);
  await C.waitForTimeout(600);
  const after2 = await (await fetch(`${BASE}/api/games/${gid}`, { headers: { cookie: cookieA } })).json();
  ok('delete by third editor synced + persisted', after2.game.partCount === 4);

  // 3-way team chat
  await B.fill('#st-chat-input', 'nice coin placement');
  await B.press('#st-chat-input', 'Enter');
  await A.waitForSelector('#studio-chat-log div:has-text("nice coin")', { timeout: 5000 });
  await C.waitForSelector('#studio-chat-log div:has-text("nice coin")', { timeout: 5000 });
  ok('studio team chat reaches all three editors', true);
  for (const p of pages) { await p.click('#st-exit'); await p.waitForSelector('#new-name'); }

  // ---- friends presence with 3 users ----
  const cookieB = (await B.context().cookies()).map((c) => `${c.name}=${c.value}`).join('; ');
  for (const n of [NAMES[1], NAMES[2]]) {
    await fetch(`${BASE}/api/friends/request`, { method: 'POST', headers: { 'Content-Type': 'application/json', cookie: cookieA }, body: JSON.stringify({ username: n }) });
  }
  // B and C accept via UI
  for (const p of [B, C]) {
    await p.goto(BASE + '/#/friends');
    await p.waitForSelector(`.friend-row:has-text("${NAMES[0]}") .btn:has-text("Accept")`);
    await p.click(`.friend-row:has-text("${NAMES[0]}") .btn:has-text("Accept")`);
    await p.waitForTimeout(300);
  }
  // C goes in-game; A checks presence + Join button
  await C.goto(BASE + '/#/play/' + obby.id);
  await C.waitForSelector('#game-root canvas');
  await A.goto(BASE + '/#/friends');
  await A.waitForSelector(`.friend-row:has-text("${NAMES[2]}")`);
  await A.waitForFunction((n) => {
    const row = [...document.querySelectorAll('.friend-row')].find((r) => r.textContent.includes(n));
    return row && /Playing/.test(row.textContent);
  }, NAMES[2], { timeout: 8000 });
  ok('friends page shows third player "Playing Tower of Bother"', true);
  const joinBtn = await A.locator(`.friend-row:has-text("${NAMES[2]}") a:has-text("Join")`).count();
  ok('Join button offered for in-game friend', joinBtn === 1);
  // A joins via the button → lands in same lobby
  await A.click(`.friend-row:has-text("${NAMES[2]}") a:has-text("Join")`);
  await A.waitForSelector('#game-root canvas');
  await A.waitForFunction(() => document.querySelectorAll('#hud-lb .lb-row').length >= 2, { timeout: 8000 });
  ok('Join-friend drops A into the same game', true);
  await A.screenshot({ path: `${SHOTS}/3p-3-joined-friend.png` });

  console.log('\nConsole/page errors: ' + (errors.length ? '\n' + errors.join('\n') : 'none'));
  await browser.close();
  console.log(`${pass} passed, ${fail} failed`);
  process.exit(fail || errors.length ? 1 : 0);
})().catch((e) => { console.error('TEST CRASH:', e.message); process.exit(1); });
